const SEED = [{"origem": "livelo_psm", "titulo": "PSM — Fluxo do repositório (visão geral)", "conteudo": "O repositório PSM (Problem-Solution Mapping) organiza o ciclo completo de experimentação: Metas SMART → Problemas (mapeados, validados e priorizados) → Categorias de problemas (score de gravidade) → Hipóteses e Soluções (priorizadas por score) → Plano de Testes → Resultados (positivo/negativo/inconclusivo) → Insights documentados. Cada problema e hipótese referencia a meta SMART via hashtag (ex.: #RECEITA). Nada entra em teste sem problema validado e hipótese priorizada.", "tags": "metodologia,processo,experimentacao,psm", "etapa_funil": "todas", "vertical": "todas", "fonte": "Livelo — Repositório PSM"}, {"origem": "livelo_psm", "titulo": "PSM — Metas SMART com hashtag", "conteudo": "Todo objetivo de negócio é documentado no formato SMART: Specific (o que deseja alcançar), Measurable (como medir — relatório/fonte), Achievable (é possível?), Relevant (condiz com objetivos da empresa e contexto atual?), Time-bound (prazo). Cada meta recebe uma hashtag-categoria (ex.: #RECEITA — 'Aumentar a receita direta online em 2% YoY, medida por relatório mensal, em 12 meses'). Problemas e hipóteses citam a hashtag da meta relacionada, garantindo alinhamento vertical.", "tags": "metas,smart,objetivos,alinhamento,okr", "etapa_funil": "todas", "vertical": "todas", "fonte": "Livelo — Repositório PSM"}, {"origem": "livelo_psm", "titulo": "PSM — Registro de problema: campos obrigatórios", "conteudo": "Um problema bem registrado tem: área de negócio demandante, produto, status, enunciado do problema, categoria, meta relacionada (#hashtag), descrição, EVIDÊNCIA (dado que comprova), localização (URL/tela/componente), dispositivo, canal, e validação: 'o problema foi validado utilizando plataformas de análise (GA, Hotjar etc.) e/ou pesquisas com usuários?' + quem validou + veredito 'problema válido?'. Problema sem evidência quantitativa ou qualitativa não avança para hipótese.", "tags": "problema,evidencia,validacao,ga4,hotjar,clarity,pesquisa", "etapa_funil": "todas", "vertical": "todas", "fonte": "Livelo — Repositório PSM"}, {"origem": "livelo_psm", "titulo": "PSM — Priorização de problemas (scores)", "conteudo": "Score do problema = soma de 3 critérios com pesos: 'Quão difícil será resolver?' (Alto=-10, Médio=10, Baixo=20 — dificuldade alta REDUZ o score), 'Quão grande é esse problema?' (Alto=20, Médio=10, Baixo=0), 'Está em alinhamento com as metas SMART prioritárias?' (Alto=30, Médio=20, Baixo=10, Não alinhado=-10). Score máximo 70, normalizado para 0-100. Problemas com maior score entram primeiro no backlog de hipóteses.", "tags": "priorizacao,score,problema,dificuldade,impacto,alinhamento", "etapa_funil": "todas", "vertical": "todas", "fonte": "Livelo — Repositório PSM"}, {"origem": "livelo_psm", "titulo": "PSM — Categorias de problemas e score de gravidade", "conteudo": "Problemas são agrupados em categorias (ex.: Product Info — 'problemas relacionados à forma de apresentação e aos conteúdos aplicados nas descrições dos produtos'). O time vota nas categorias mais críticas; o score de gravidade da categoria = score médio dos problemas válidos × proporção de problemas válidos. Priorizam-se categorias, não problemas isolados — ataca-se a causa sistêmica.", "tags": "categoria,gravidade,priorizacao,product-info", "etapa_funil": "todas", "vertical": "todas", "fonte": "Livelo — Repositório PSM"}, {"origem": "livelo_psm", "titulo": "PSM — Formato de hipótese (Acredito que se…)", "conteudo": "Hipótese no formato Livelo: 'Acredito que se [alteração específica], [público-alvo] terá [benefício/comportamento esperado]. Se eu estiver certo, veremos [métrica que muda].' Exemplo real: 'Acredito que se transformarmos a descrição dos produtos da seção Acessórios de Informática para um formato de tópicos, os usuários terão maior facilidade para ler as características. Se eu estiver certo, veremos uma redução nas trocas e devoluções destes produtos.'", "tags": "hipotese,formato,formulacao,teste", "etapa_funil": "todas", "vertical": "todas", "fonte": "Livelo — Repositório PSM"}, {"origem": "livelo_psm", "titulo": "PSM — Fórmula de hipótese do backlog (Sabendo que / Fazendo / Esperamos)", "conteudo": "Estrutura de experimento do backlog: SABENDO QUE [problema com evidência em dados] — ex.: 'o carrossel da home possui taxa de cliques de apenas x%, enquanto o banner das demais páginas possui y%'; FAZENDO [alteração a ser aplicada na variante] — ex.: 'a subida do carrossel para a primeira dobra'; ESPERAMOS ENTENDER SE [comportamento esperado/aprendizado] — ex.: 'os usuários não clicavam por não ver o componente ou porque o conteúdo não era relevante'. A hipótese completa concatena: 'Ao fazer X, esperamos entender se Y, dado que Z.'", "tags": "hipotese,backlog,sabendo-fazendo-esperamos,aprendizado", "etapa_funil": "todas", "vertical": "todas", "fonte": "Livelo — Repositório PSM"}, {"origem": "livelo_psm", "titulo": "PSM — Nomenclatura de experimento", "conteudo": "Nome do experimento segue o padrão: [ação + elemento + página/categoria + canal]. Exemplos: 'Realocar carrossel da home do site'; 'Transformar em tópicos a descrição dos produtos de informática das páginas de Usar Pontos do site e aplicativo'. O nome deve permitir entender o teste sem abrir o card.", "tags": "nomenclatura,experimento,padrao,documentacao", "etapa_funil": "todas", "vertical": "todas", "fonte": "Livelo — Repositório PSM"}, {"origem": "livelo_psm", "titulo": "PSM — Priorização de hipóteses (5 critérios, max 60)", "conteudo": "Score da hipótese = soma de 5 critérios: Esforço necessário (Alto=0, Médio=5, Baixo=10 — esforço baixo PONTUA MAIS), Probabilidade de veracidade da hipótese (Alto=10, Médio=5, Baixo=-5), Probabilidade de implementação (Alto=10, Médio=5, Baixo=-5), Impacto da implementação no negócio (Alto=20, Médio=10, Baixo=3), Alinhamento com metas SMART e problemas válidos (Alto=10, Médio=5, Baixo=-5, Não alinhado=-10). Máximo 60, normalizado 0-100. Complementa o ICE com dimensões de veracidade e alinhamento.", "tags": "priorizacao,score,hipotese,esforco,impacto,ice", "etapa_funil": "todas", "vertical": "todas", "fonte": "Livelo — Repositório PSM"}, {"origem": "livelo_psm", "titulo": "PSM — KPI principal, secundários e NEGATIVOS (guardrails)", "conteudo": "Todo experimento define: KPI PRINCIPAL (a métrica que decide sucesso/insucesso — uma só), KPIs SECUNDÁRIOS (métricas que podem ser impactadas positivamente) e KPIs NEGATIVOS (guardrails — métricas que podem ser afetadas negativamente e precisam ser monitoradas; ex.: aumentar cliques no carrossel não pode derrubar tempo na página ou receita). Um teste que ganha no KPI principal mas degrada um guardrail não é vitória.", "tags": "kpi,guardrail,metricas,kpis-negativas,monitoramento", "etapa_funil": "todas", "vertical": "todas", "fonte": "Livelo — Repositório PSM"}, {"origem": "livelo_psm", "titulo": "PSM — Calculadora de relevância estatística (95%)", "conteudo": "Um experimento só é conclusivo com significância estatística de 95%: registram-se visitas e conversões de Controle e Variante; calculam-se taxa de conversão, uplift, erro padrão, z-score, p-valor e intervalos de confiança de cada versão. Regra: declarar vencedor somente com p-valor < 0,05 e intervalos de confiança que não se sobreponham de forma relevante. Exemplo do repositório: controle 2000 visitas/200 conversões (10%) vs variante 2000/250 (12,5%) → uplift 25%, p≈0,006 → RELEVANTE.", "tags": "significancia,estatistica,p-valor,ab-test,confianca,relevancia", "etapa_funil": "todas", "vertical": "todas", "fonte": "Livelo — Repositório PSM"}, {"origem": "livelo_psm", "titulo": "PSM — Calculadora de potencial (funil → R$)", "conteudo": "Potencial financeiro de uma otimização é estimado etapa a etapa do funil: para cada etapa (ex.: Home → listagem → produto → carrinho → sucesso) registram-se sessões e % de passagem para a próxima etapa; simula-se o incremental de passagem na etapa alvo (ex.: +2 p.p. na página de produto); recalcula-se o funil e obtém-se conversões incrementais × ticket médio = retorno potencial mensal em R$. Exemplo Livelo: +2 p.p. em /produto → +43 conversões/mês → R$ 11,5 mi incremental sobre base de R$ 575,7 mi. Sempre apresentar o cálculo aberto (auditável).", "tags": "potencial,funil,receita,calculo,uplift,ticket-medio,oportunidade", "etapa_funil": "todas", "vertical": "e-commerce", "fonte": "Livelo — Repositório PSM"}, {"origem": "livelo_psm", "titulo": "PSM — Plano de teste: estrutura do documento", "conteudo": "O plano de testes contém: RESUMO (ID, categoria do problema, problema, nome e descrição da hipótese, KPI principal, KPIs secundários, página/tela, frame/componente, canal, dispositivo/SO, meta relacionada), CARD JIRA vinculado, TIPO DE TESTE (A/B/n, Multivariado, Split URL), PLATAFORMA, cronograma (início, final previsto quando houver amostra suficiente, duração em semanas), variações com alocação de tráfego e screenshots (controle vs B), descrição do problema na versão original e da solução na variante, informações para os desenvolvedores, riscos e link de preview.", "tags": "plano-de-teste,documentacao,jira,ab-test,template", "etapa_funil": "todas", "vertical": "todas", "fonte": "Livelo — Repositório PSM"}, {"origem": "livelo_psm", "titulo": "PSM — QA de métricas antes de rodar o teste", "conteudo": "Checklist de QA obrigatório antes de iniciar o experimento: para CADA métrica de otimização (principal e secundárias), registrar a fonte de acompanhamento (ex.: relatório X do GA, relatório financeiro) e verificar se o tagueamento/coleta do dado está funcionando corretamente, com um responsável nomeado pelo QA de cada métrica. Teste com tracking quebrado é dado perdido — validar ANTES, nunca durante.", "tags": "qa,tagueamento,tracking,ga4,metricas,checklist", "etapa_funil": "todas", "vertical": "todas", "fonte": "Livelo — Repositório PSM"}, {"origem": "livelo_psm", "titulo": "PSM — Segmentação e alocação do teste", "conteudo": "Todo teste define segmentação explícita: browsers/dispositivos incluídos (ex.: desktop moderno Chrome/FF/Safari/Edge + mobile iPhone/Android) e excluídos (ex.: tablets), audiência/URL targeting com padrões de inclusão (ex.: páginas que contêm /produto/) e exclusão (ex.: páginas de debug), e alocação de tráfego por variação (% controle vs % variante). Segmentação mal definida contamina a amostra e invalida o resultado.", "tags": "segmentacao,targeting,alocacao,trafego,amostra", "etapa_funil": "todas", "vertical": "todas", "fonte": "Livelo — Repositório PSM"}, {"origem": "livelo_psm", "titulo": "PSM — Status de problemas e hipóteses (workflow)", "conteudo": "Fluxo de status padronizado. Problemas: Novo → Em validação → Backlog → Em andamento → Resolvido | Declinado. Hipóteses: Backlog → Em configuração → Em andamento → Finalizado | Despriorizado | Rollout (quando a variante vence e vai para 100% do tráfego). Status permitem acompanhar o pipeline no dashboard executivo (overview por área de negócio).", "tags": "status,workflow,pipeline,rollout,backlog", "etapa_funil": "todas", "vertical": "todas", "fonte": "Livelo — Repositório PSM"}, {"origem": "livelo_psm", "titulo": "PSM — Registro de resultados e insights", "conteudo": "Ao final do teste registram-se: visitas e conversões de A (controle) e B, taxas de conversão, uplift, p-valor e EFETIVIDADE (Positivo | Negativo | Inconclusivo) + INSIGHTS (o que aprendemos, independente de ganhar). Teste negativo ou inconclusivo também gera aprendizado documentado — alimenta o repositório e evita repetir apostas ruins. Atualizações durante o teste (qualquer alteração) são registradas com data, solicitante e impacto no andamento.", "tags": "resultados,insights,aprendizado,efetividade,documentacao", "etapa_funil": "todas", "vertical": "todas", "fonte": "Livelo — Repositório PSM"}, {"origem": "livelo_psm", "titulo": "PSM — Documentação de experimento (impacto financeiro + OKR)", "conteudo": "Ficha de documentação do experimento: ferramenta, nome (ação+elemento+página+canal), Sabendo que (evidência), Fazendo (alteração), Esperamos que (comportamento), tipo de experimento, KPI de sucesso, KPIs secundárias, KPIs negativas, taxa de conversão/visitas/conversões dos últimos 30 dias (baseline), URL, dispositivo, ticket médio atual, IMPACTO FINANCEIRO ESPERADO (cálculo aberto) e OKR atrelada. Baseline de 30 dias é obrigatório para dimensionar o efeito.", "tags": "documentacao,baseline,impacto-financeiro,okr,experimento", "etapa_funil": "todas", "vertical": "todas", "fonte": "Livelo — Repositório PSM"}, {"origem": "referencia_externa", "titulo": "Baymard — Benchmarks de checkout e-commerce", "conteudo": "Referências Baymard Institute para e-commerce: abandono médio de checkout ~70%; taxa saudável carrinho→checkout 55-65%; checkout→compra 40-55%; principais causas de abandono: custos extras revelados tarde (frete/taxas), obrigação de criar conta, checkout longo/complexo (ideal 12-14 elementos de formulário), falta de confiança no pagamento, erros de validação mal comunicados. Comparar sempre a taxa real do cliente contra essas faixas antes de estimar uplift.", "tags": "baymard,checkout,benchmark,abandono,e-commerce,carrinho", "etapa_funil": "checkout", "vertical": "e-commerce", "fonte": "Baymard Institute (referência de mercado)"}, {"origem": "referencia_externa", "titulo": "NN/g — 10 heurísticas de Nielsen aplicadas a conversão", "conteudo": "Heurísticas de usabilidade com maior efeito em conversão: visibilidade do status do sistema (feedback de progresso no funil), correspondência com o mundo real (linguagem do usuário, não jargão), prevenção de erros (validação inline em formulários), reconhecimento em vez de memorização (resumo do pedido sempre visível), flexibilidade (guest checkout, múltiplos pagamentos), design minimalista (remover distrações no fluxo de decisão), ajudar a reconhecer/recuperar erros (mensagens específicas com correção sugerida). Citar a heurística violada + evidência quantitativa ao registrar problema.", "tags": "nielsen,heuristica,usabilidade,ux,formularios", "etapa_funil": "todas", "vertical": "todas", "fonte": "Nielsen Norman Group (referência de mercado)"}, {"origem": "referencia_externa", "titulo": "WCAG 2.2 — Acessibilidade que afeta conversão", "conteudo": "Critérios WCAG A/AA com impacto direto em conversão: contraste mínimo 4.5:1 em texto e CTAs (usuários não clicam no que não leem), alvos de toque ≥24px (mobile), foco visível em navegação por teclado, labels e mensagens de erro programaticamente associadas a campos, não depender só de cor para comunicar estado/erro, evitar timeout curto em checkout. Falhas de acessibilidade aparecem no Clarity como rage clicks e abandono em formulários — cruzar os sinais.", "tags": "wcag,acessibilidade,contraste,mobile,formularios,rage-clicks", "etapa_funil": "todas", "vertical": "todas", "fonte": "WCAG 2.2 (referência de mercado)"}, {"origem": "referencia_externa", "titulo": "GA4 — Eventos de funil e-commerce padrão", "conteudo": "Funil e-commerce GA4 canônico: page_view → view_item_list → select_item → view_item → add_to_cart → view_cart → begin_checkout → add_shipping_info → add_payment_info → purchase. Para lead-gen: form_start → form_submit / generate_lead / sign_up. Quedas anormais entre eventos adjacentes indicam o gargalo; ausência de evento intermediário (ex.: add_shipping_info) geralmente é falha de tagueamento, não de UX — validar coleta antes de diagnosticar comportamento.", "tags": "ga4,eventos,funil,tagueamento,e-commerce,lead", "etapa_funil": "todas", "vertical": "todas", "fonte": "Google Analytics 4 (referência de mercado)"}, {"origem": "referencia_externa", "titulo": "Clarity — Sinais comportamentais e leitura", "conteudo": "Microsoft Clarity fornece sinais de fricção: rage clicks (cliques repetidos em elemento que não responde — botão quebrado ou expectativa de interatividade), dead clicks (cliques sem efeito), quick backs (retorno imediato à página anterior — expectativa quebrada), excessive scrolling (conteúdo desorganizado ou CTA fora da dobra). Regra de leitura: rage clicks acima de ~3-4% das sessões numa página do funil é sinal forte; sempre correlacionar com a queda de passagem no GA4 na mesma página para virar problema válido.", "tags": "clarity,rage-clicks,dead-clicks,comportamento,friccao", "etapa_funil": "todas", "vertical": "todas", "fonte": "Microsoft Clarity (referência de mercado)"}];
