const b = ($json.body) || {};
const docs = Array.isArray(b) ? b : (Array.isArray(b.documentos) ? b.documentos : [b]);
const agora = new Date().toISOString();
const out = [];
for (const d of docs) {
  if (!d || !d.conteudo) continue;
  const base = { origem: d.origem || 'documento_interno', titulo: d.titulo || 'Documento sem título', tags: d.tags || '', etapa_funil: d.etapa_funil || 'todas', vertical: d.vertical || 'todas', fonte: d.fonte || '', criado_em: agora };
  const txt = String(d.conteudo);
  if (txt.length <= 1400) { out.push({ json: { ...base, conteudo: txt } }); }
  else { let i = 0, p = 1; while (i < txt.length) { out.push({ json: { ...base, titulo: base.titulo + ' (parte ' + p + ')', conteudo: txt.slice(i, i + 1400) } }); i += 1400; p++; } }
}
if (!out.length) return [{ json: { vazio: true, criado_em: agora, origem: '', titulo: '', conteudo: '', tags: '', etapa_funil: '', vertical: '', fonte: '' } }];
return out;

